SourceCode.Declaration:
[DataContractAttribute]
class HSMobileOpsJournalListRequest
{
    DataAreaId       dataAreaId;
    InventLocationId warehouseId;

    str userId;
    boolean includeDone;
}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

/// <summary>
/// The worker's assigned warehouse - see HSMobileOpsUserWarehouse. Required, unlike
/// HSMobileOpsOnHandRequest's optional warehouse filter: a counting journal list with no
/// warehouse scope at all would be every open count in the company, which is not a question
/// this screen ever means to ask.
/// </summary>
[DataMemberAttribute('WarehouseId')]
public InventLocationId parmWarehouseId(InventLocationId _value = warehouseId)
{
    warehouseId = _value;
    return warehouseId;
}

/// <summary>
/// Who is asking - an external counter only sees journals assigned to their team.
/// </summary>
[DataMemberAttribute('UserId')]
public str parmUserId(str _value = userId)
{
    userId = _value;
    return userId;
}

/// <summary>
/// Also list journals finished for this user, each with a DoneNote: the handheld's Done tab.
/// Off when absent, so an older app sees only open journals.
/// </summary>
[DataMemberAttribute('IncludeDone')]
public boolean parmIncludeDone(boolean _value = includeDone)
{
    includeDone = _value;
    return includeDone;
}
